import { FormEvent, useCallback, useEffect, useMemo, useState } from "react";
import {
  Activity, Archive, ArrowDownToLine, ArrowUpRight, Banknote, Bell, Boxes,
  Building2, Check, ChevronDown, CircleAlert, ClipboardList, CreditCard,
  FileCheck2, FilePlus2, FileText, LayoutDashboard, LogOut, Menu, Package,
  Pencil, Plus, Printer, RefreshCw, Search, Settings as SettingsIcon,
  ShieldCheck, ShoppingCart, Trash2, Truck, Users, Wallet, X, ChartNoAxesCombined
} from "lucide-react";

type Row = Record<string, any>;
type Session = { user: { id: string; email: string }; company: { id: string; name: string; status?: string; settings?: Row }; role: string };
type Module = "Overview" | "Sales" | "Purchases" | "Inventory" | "Customers" | "Suppliers" | "Finance" | "Reports" | "Subscription" | "Settings";
const API = (import.meta as any).env?.VITE_API_URL || "http://localhost:4000";
const NAV: { name: Module; icon: any; description: string }[] = [
  { name: "Overview", icon: LayoutDashboard, description: "Business overview" },
  { name: "Sales", icon: ShoppingCart, description: "Quotations, orders and invoices" },
  { name: "Purchases", icon: Truck, description: "Purchase orders and supplier invoices" },
  { name: "Inventory", icon: Package, description: "Products, stock and warehouses" },
  { name: "Customers", icon: Users, description: "Customer records" },
  { name: "Suppliers", icon: Building2, description: "Supplier records" },
  { name: "Finance", icon: Wallet, description: "Receipts, payments and expenses" },
  { name: "Reports", icon: ChartNoAxesCombined, description: "Operational reports and exports" },
  { name: "Subscription", icon: CreditCard, description: "Plan and deployment status" },
  { name: "Settings", icon: SettingsIcon, description: "Company and local system settings" },
];

function money(value: unknown) { return `RM ${Number(value ?? 0).toLocaleString("en-MY", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`; }
function dateText(value: unknown) { if (!value) return "—"; const d = new Date(String(value)); return Number.isNaN(d.valueOf()) ? "—" : d.toLocaleDateString("en-MY", { day: "2-digit", month: "short", year: "numeric" }); }
function dateTimeText(value: unknown) { if (!value) return "—"; const d = new Date(String(value)); return Number.isNaN(d.valueOf()) ? "—" : d.toLocaleString("en-MY", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" }); }
function statusClass(status: unknown) { const s = String(status ?? "").toLowerCase(); return s === "issued" || s === "active" || s === "paid" ? "status status-green" : s === "voided" || s === "archived" || s === "suspended" ? "status status-red" : "status status-amber"; }
function htmlEscape(v: unknown) { return String(v ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]!)); }

async function api<T = any>(path: string, options: RequestInit = {}): Promise<T> {
  const token = localStorage.getItem("sastha_erp_token");
  const headers: Record<string, string> = { "Content-Type": "application/json", ...(options.headers as Record<string, string> ?? {}) };
  if (token) headers.Authorization = `Bearer ${token}`;
  let response: Response;
  try { response = await fetch(`${API}${path}`, { ...options, headers }); }
  catch {
    const origin = typeof window !== "undefined" ? window.location.origin : "your browser origin";
    throw new Error(`The browser could not connect to ${API}. Check that the ERP API is running and the database is ready. If the API is running, open the website using http://localhost:5173 or http://127.0.0.1:5173; current website origin: ${origin}.`);
  }
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(payload.error || `Request failed (${response.status})`);
  return payload as T;
}

export default function App() {
  const [session, setSession] = useState<Session | null>(null);
  const [authMode, setAuthMode] = useState<"login" | "register">("login");
  const [authLoading, setAuthLoading] = useState(false);
  const [starting, setStarting] = useState(true);
  const [active, setActive] = useState<Module>("Overview");
  const [mobileOpen, setMobileOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [search, setSearch] = useState("");
  const [notice, setNotice] = useState<{ type: "success" | "error" | "info"; text: string } | null>(null);
  const [loading, setLoading] = useState(false);
  const [busy, setBusy] = useState(false);
  const [modal, setModal] = useState<string | null>(null);
  const [editRow, setEditRow] = useState<Row | null>(null);
  const [docType, setDocType] = useState("INVOICE");
  const [docLines, setDocLines] = useState([{ productId: "", description: "", quantity: "1", unitPrice: "0" }]);
  const [dashboard, setDashboard] = useState<Row | null>(null);
  const [customers, setCustomers] = useState<Row[]>([]);
  const [suppliers, setSuppliers] = useState<Row[]>([]);
  const [products, setProducts] = useState<Row[]>([]);
  const [warehouses, setWarehouses] = useState<Row[]>([]);
  const [sales, setSales] = useState<Row[]>([]);
  const [purchases, setPurchases] = useState<Row[]>([]);
  const [receipts, setReceipts] = useState<Row[]>([]);
  const [payments, setPayments] = useState<Row[]>([]);
  const [expenses, setExpenses] = useState<Row[]>([]);
  const [movements, setMovements] = useState<Row[]>([]);
  const [report, setReport] = useState<Row | null>(null);
  const [settings, setSettings] = useState<Row | null>(null);
  const [notifications, setNotifications] = useState<Row[]>([]);
  const [noticeOpen, setNoticeOpen] = useState(false);

  const pushNotice = (type: "success" | "error" | "info", text: string) => { setNotice({ type, text }); window.setTimeout(() => setNotice(null), 5200); };

  const loadModule = useCallback(async (module: Module) => {
    setLoading(true);
    try {
      if (module === "Overview") {
        const r = await api<{ data: Row }>("/api/dashboard"); setDashboard(r.data);
      } else if (module === "Customers") {
        const r = await api<{ data: Row[] }>("/api/customers?all=true"); setCustomers(r.data);
      } else if (module === "Suppliers") {
        const r = await api<{ data: Row[] }>("/api/suppliers?all=true"); setSuppliers(r.data);
      } else if (module === "Inventory") {
        const [p, w, m] = await Promise.all([api<{ data: Row[] }>("/api/products?all=true"), api<{ data: Row[] }>("/api/warehouses"), api<{ data: Row[] }>("/api/stock/movements")]); setProducts(p.data); setWarehouses(w.data); setMovements(m.data);
      } else if (module === "Sales") {
        const [d, c, p, w] = await Promise.all([api<{ data: Row[] }>("/api/sales-documents"), api<{ data: Row[] }>("/api/customers"), api<{ data: Row[] }>("/api/products"), api<{ data: Row[] }>("/api/warehouses")]); setSales(d.data); setCustomers(c.data); setProducts(p.data); setWarehouses(w.data);
      } else if (module === "Purchases") {
        const [d, s, p, w] = await Promise.all([api<{ data: Row[] }>("/api/purchase-documents"), api<{ data: Row[] }>("/api/suppliers"), api<{ data: Row[] }>("/api/products"), api<{ data: Row[] }>("/api/warehouses")]); setPurchases(d.data); setSuppliers(s.data); setProducts(p.data); setWarehouses(w.data);
      } else if (module === "Finance") {
        const [r, p, e, s, pd, c, su] = await Promise.all([api<{data:Row[]}>("/api/receipts"), api<{data:Row[]}>("/api/supplier-payments"), api<{data:Row[]}>("/api/expenses"), api<{data:Row[]}>("/api/sales-documents"), api<{data:Row[]}>("/api/purchase-documents"), api<{data:Row[]}>("/api/customers"), api<{data:Row[]}>("/api/suppliers")]); setReceipts(r.data); setPayments(p.data); setExpenses(e.data); setSales(s.data); setPurchases(pd.data); setCustomers(c.data); setSuppliers(su.data);
      } else if (module === "Reports") {
        const r = await api<{data:Row}>("/api/reports/summary"); setReport(r.data);
      } else if (module === "Settings") {
        const [s, w, logs] = await Promise.all([api<{data:Row}>("/api/settings"), api<{data:Row[]}>("/api/warehouses"), api<{data:Row[]}>("/api/audit-logs")]); setSettings(s.data); setWarehouses(w.data); setMovements(logs.data);
      } else if (module === "Subscription") {
        const r = await api<{ data: Row; requests: Row[] }>("/api/subscription"); setSettings({ subscription: r.data, planRequests: r.requests });
      }
    } catch (error) { pushNotice("error", error instanceof Error ? error.message : "Could not load this module."); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => {
    const token = localStorage.getItem("sastha_erp_token");
    if (!token) { setStarting(false); return; }
    api<{ user: Session["user"]; company: Session["company"]; role: string }>("/api/me").then(s => {
      setSession(s); setStarting(false); void loadModule("Overview");
    }).catch(() => { localStorage.removeItem("sastha_erp_token"); setStarting(false); });
  }, [loadModule]);

  useEffect(() => { if (session) { api<{data:Row[]}>('/api/notifications').then(r=>setNotifications(r.data)).catch(()=>undefined); } }, [session, active, dashboard]);

  async function authenticate(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); setAuthLoading(true);
    const fd = new FormData(e.currentTarget);
    const body = authMode === "register"
      ? { companyName: String(fd.get("companyName") ?? ""), email: String(fd.get("email") ?? ""), password: String(fd.get("password") ?? "") }
      : { email: String(fd.get("email") ?? ""), password: String(fd.get("password") ?? "") };
    try {
      const r = await api<any>(authMode === "register" ? "/api/auth/register" : "/api/auth/login", { method: "POST", body: JSON.stringify(body) });
      localStorage.setItem("sastha_erp_token", r.token);
      const me = await api<Session>("/api/me"); setSession(me); setActive("Overview"); await loadModule("Overview"); pushNotice("success", authMode === "register" ? "Company workspace created successfully." : "Signed in successfully.");
    } catch (error) { pushNotice("error", error instanceof Error ? error.message : "Unable to sign in."); }
    finally { setAuthLoading(false); }
  }

  function logout() { localStorage.removeItem("sastha_erp_token"); setSession(null); setDashboard(null); setActive("Overview"); setNotice(null); }
  function navigate(module: Module) { setActive(module); setMobileOpen(false); setModal(null); void loadModule(module); }
  function openNew(kind: string, type?: string) {
    setEditRow(null); setModal(kind); if (type) setDocType(type); setDocLines([{ productId: "", description: "", quantity: "1", unitPrice: "0" }]);
    // Quick actions opened from the dashboard preload the related dropdown data too.
    if (kind === "salesDoc") void Promise.all([api<{data:Row[]}>("/api/customers"), api<{data:Row[]}>("/api/products"), api<{data:Row[]}>("/api/warehouses")]).then(([c,p,w])=>{setCustomers(c.data);setProducts(p.data);setWarehouses(w.data);}).catch(e=>pushNotice("error",e instanceof Error?e.message:"Could not load sales form data."));
    if (kind === "purchaseDoc") void Promise.all([api<{data:Row[]}>("/api/suppliers"), api<{data:Row[]}>("/api/products"), api<{data:Row[]}>("/api/warehouses")]).then(([s,p,w])=>{setSuppliers(s.data);setProducts(p.data);setWarehouses(w.data);}).catch(e=>pushNotice("error",e instanceof Error?e.message:"Could not load purchase form data."));
    if (kind === "stock") void Promise.all([api<{data:Row[]}>("/api/products?all=true"),api<{data:Row[]}>("/api/warehouses")]).then(([p,w])=>{setProducts(p.data);setWarehouses(w.data);}).catch(e=>pushNotice("error",e instanceof Error?e.message:"Could not load stock form data."));
    if (kind === "receipt" || kind === "payment") void Promise.all([api<{data:Row[]}>("/api/customers"),api<{data:Row[]}>("/api/suppliers"),api<{data:Row[]}>("/api/sales-documents"),api<{data:Row[]}>("/api/purchase-documents")]).then(([c,s,sd,pd])=>{setCustomers(c.data);setSuppliers(s.data);setSales(sd.data);setPurchases(pd.data);}).catch(e=>pushNotice("error",e instanceof Error?e.message:"Could not load payment form data."));
    if (kind === "settings") void api<{data:Row}>("/api/settings").then(r=>setSettings(r.data)).catch(e=>pushNotice("error",e instanceof Error?e.message:"Could not load company settings."));
  }
  function openEdit(kind: string, row: Row) { setEditRow(row); setModal(kind); }

  async function submitForm(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); if (!modal) return; setBusy(true);
    const fd = new FormData(e.currentTarget); const val = (name: string) => String(fd.get(name) ?? "").trim();
    const num = (name: string, fallback = 0) => { const n = Number(fd.get(name)); return Number.isFinite(n) ? n : fallback; };
    try {
      let path = "", method = "POST", body: Row = {};
      if (modal === "customer" || modal === "supplier") {
        const key = modal === "customer" ? "customers" : "suppliers"; path = `/api/${key}${editRow ? `/${editRow.id}` : ""}`; method = editRow ? "PUT" : "POST";
        body = { name: val("name"), email: val("email"), phone: val("phone"), tin: val("tin"), registrationNo: val("registrationNo"), address: val("address"), ...(editRow ? { active: editRow.active } : {}) };
      } else if (modal === "product") {
        path = `/api/products${editRow ? `/${editRow.id}` : ""}`; method = editRow ? "PUT" : "POST";
        body = { sku: val("sku"), name: val("name"), barcode: val("barcode"), description: val("description"), unitCode: val("unitCode") || "UNIT", unitPrice: num("unitPrice"), unitCost: num("unitCost") };
      } else if (modal === "warehouse") {
        path = "/api/warehouses"; body = { code: val("code"), name: val("name") };
      } else if (modal === "salesDoc") {
        path = "/api/sales-documents"; body = { customerId: val("customerId"), type: docType, documentNo: val("documentNo") || undefined, discount: num("discount"), taxRate: num("taxRate"), lines: docLines.map(x=>({productId:x.productId||undefined, description:x.description, quantity:Number(x.quantity), unitPrice:Number(x.unitPrice)})) };
      } else if (modal === "purchaseDoc") {
        path = "/api/purchase-documents"; body = { supplierId: val("supplierId"), type: docType, documentNo: val("documentNo") || undefined, taxRate: num("taxRate"), lines: docLines.map(x=>({productId:x.productId||undefined, description:x.description, quantity:Number(x.quantity), unitPrice:Number(x.unitPrice)})) };
      } else if (modal === "stock") {
        path = "/api/stock/movements"; const quantity = num("quantity"); body = { productId: val("productId"), warehouseId: val("warehouseId"), type: val("type"), quantityDelta: val("direction") === "decrease" ? -Math.abs(quantity) : Math.abs(quantity), unitCost: val("unitCost") ? num("unitCost") : undefined, reason: val("reason") };
      } else if (modal === "receipt") {
        path = "/api/receipts"; body = { customerId: val("customerId"), documentId: val("documentId") || undefined, amount: num("amount"), method: val("method"), reference: val("reference"), note: val("note") };
      } else if (modal === "payment") {
        path = "/api/supplier-payments"; body = { supplierId: val("supplierId"), documentId: val("documentId") || undefined, amount: num("amount"), method: val("method"), reference: val("reference"), note: val("note") };
      } else if (modal === "expense") {
        path = "/api/expenses"; body = { category: val("category"), description: val("description"), amount: num("amount"), method: val("method"), reference: val("reference"), notes: val("notes") };
      } else if (modal === "settings") {
        path = "/api/settings"; method = "PUT"; body = { name: val("name"), registrationNo: val("registrationNo"), currency: val("currency") || "MYR", timezone: val("timezone") || "Asia/Kuala_Lumpur", invoicePrefix: val("invoicePrefix") || "INV" };
      }
      const response = await api<any>(path, { method, body: JSON.stringify(body) });
      setModal(null); setEditRow(null); pushNotice("success", editRow ? "Record updated." : "Record saved successfully.");
      if (modal === "settings" && response.data) setSession(s => s ? { ...s, company: { ...s.company, name: response.data.name, settings: response.data.settings } } : s);
      await loadModule(active);
    } catch (error) { pushNotice("error", error instanceof Error ? error.message : "Unable to save this record."); }
    finally { setBusy(false); }
  }

  async function archiveRecord(kind: "customers" | "suppliers" | "products", row: Row) {
    const noun = kind === "customers" ? "customer" : kind === "suppliers" ? "supplier" : "product";
    if (!window.confirm(`Archive ${noun} “${row.name}”? Its transaction history will be retained.`)) return;
    try { await api(`/api/${kind}/${row.id}`, { method: "DELETE" }); pushNotice("success", `${noun[0].toUpperCase()+noun.slice(1)} archived.`); await loadModule(active); }
    catch (error) { pushNotice("error", error instanceof Error ? error.message : "Unable to archive the record."); }
  }

  async function issueSales(row: Row) {
    let body: Row = {};
    if (["INVOICE", "CREDIT_NOTE"].includes(row.type) && row.lines?.some((l: Row) => l.productId)) {
      const wid = warehouses[0]?.id; if (!wid) { pushNotice("error", "Create a warehouse before posting this document."); return; } body.warehouseId = wid;
    }
    if (!window.confirm(`Issue ${row.documentNo}? ${row.type === "INVOICE" ? "Stock will decrease for product lines." : "The document status will change from draft to issued."}`)) return;
    try { await api(`/api/sales-documents/${row.id}/issue`, { method: "POST", body: JSON.stringify(body) }); pushNotice("success", `${row.documentNo} issued.`); await loadModule(active); }
    catch (error) { pushNotice("error", error instanceof Error ? error.message : "Unable to issue document."); }
  }
  async function issuePurchase(row: Row) {
    const body: Row = {};
    if (row.type === "SUPPLIER_INVOICE" && row.lines?.some((l: Row) => l.productId)) { if (!warehouses[0]) { pushNotice("error", "Create a warehouse before posting supplier stock."); return; } body.warehouseId = warehouses[0].id; }
    if (!window.confirm(`Issue ${row.documentNo}? Supplier-invoice product lines will be added to stock.`)) return;
    try { await api(`/api/purchase-documents/${row.id}/issue`, { method: "POST", body: JSON.stringify(body) }); pushNotice("success", `${row.documentNo} issued.`); await loadModule(active); }
    catch (error) { pushNotice("error", error instanceof Error ? error.message : "Unable to issue purchase document."); }
  }
  async function receiveOrder(row: Row) {
    if (!warehouses[0]) { pushNotice("error", "Create a warehouse first."); return; }
    if (!window.confirm(`Receive all product lines for ${row.documentNo} into ${warehouses[0].name}? Partial receiving is not enabled.`)) return;
    try { await api(`/api/purchase-documents/${row.id}/receive`, { method: "POST", body: JSON.stringify({ warehouseId: warehouses[0].id }) }); pushNotice("success", "Purchase order received into stock."); await loadModule(active); }
    catch (error) { pushNotice("error", error instanceof Error ? error.message : "Unable to receive order."); }
  }

  function exportCsv(name: string, rows: Row[]) {
    if (!rows.length) { pushNotice("info", "There are no records to export."); return; }
    const keys = [...new Set(rows.flatMap(r => Object.keys(r).filter(k => !["stockMovements", "lines", "receipts", "payments", "customer", "supplier", "document", "tenant", "createdBy"].includes(k))))];
    const csv = [keys.join(","), ...rows.map(row => keys.map(k => { let v = row[k]; if (v && typeof v === "object") v = JSON.stringify(v); return `"${String(v ?? "").replace(/"/g, '""')}"`; }).join(","))].join("\r\n");
    const blob = new Blob(["\ufeff", csv], { type: "text/csv;charset=utf-8;" }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = `${name}-${new Date().toISOString().slice(0,10)}.csv`; a.click(); URL.revokeObjectURL(url); pushNotice("success", "CSV report downloaded.");
  }
  function printSales(row: Row) {
    const win = window.open("", "_blank", "width=900,height=700"); if (!win) { pushNotice("error", "Allow pop-ups to print the document."); return; }
    const lines = (row.lines || []).map((l: Row) => `<tr><td>${htmlEscape(l.description)}</td><td style="text-align:right">${Number(l.quantity).toLocaleString()}</td><td style="text-align:right">${money(l.unitPrice)}</td><td style="text-align:right">${money(l.lineTotal)}</td></tr>`).join("");
    win.document.write(`<!doctype html><html><head><title>${htmlEscape(row.documentNo)}</title><style>body{font:14px Arial;padding:36px;color:#172b3a}header{display:flex;justify-content:space-between;border-bottom:2px solid #167b61;padding-bottom:20px;margin-bottom:24px}h1{font-size:24px}table{width:100%;border-collapse:collapse;margin-top:26px}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}th{background:#f3f7f8}.total{text-align:right;margin-top:25px;font-size:20px;font-weight:bold}</style></head><body><header><div><h1>SASTHA INFINITE ENTERPRISE</h1><div>ERP document</div></div><div><h2>${htmlEscape(row.type?.replaceAll("_"," "))}</h2><strong>${htmlEscape(row.documentNo)}</strong><p>Date: ${dateText(row.issuedAt || row.createdAt)}</p><p>Status: ${htmlEscape(row.status)}</p></div></header><h3>Bill to: ${htmlEscape(row.customer?.name || "")}</h3><table><thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Line total</th></tr></thead><tbody>${lines}</tbody></table><div class="total">Subtotal: ${money(row.subtotal)}<br>Discount: ${money(row.discount)}<br>Tax: ${money(row.taxTotal)}<br>Total: ${money(row.grandTotal)}</div><p style="margin-top:70px;color:#667">Generated by Sastha Infinite ERP local system.</p><script>window.onload=()=>window.print()</script></body></html>`); win.document.close();
  }

  const visibleRows = useMemo(() => {
    const q = search.trim().toLowerCase(); if (!q) return null;
    const source = active === "Customers" ? customers : active === "Suppliers" ? suppliers : active === "Inventory" ? products : active === "Sales" ? sales : active === "Purchases" ? purchases : active === "Finance" ? [...receipts, ...payments, ...expenses] : [];
    return source.filter(r => JSON.stringify(r).toLowerCase().includes(q));
  }, [search, active, customers, suppliers, products, sales, purchases, receipts, payments, expenses]);

  if (starting) return <div className="boot-screen"><div className="boot-logo"><Boxes size={26}/></div><strong>Sastha Infinite ERP</strong><span>Checking your local workspace…</span></div>;
  if (!session) return <div className="auth-layout"><div className="auth-brand"><div className="brand-mark"><Boxes size={25}/></div><div><b>SASTHA INFINITE</b><small>BUSINESS ERP</small></div></div><div className="auth-card"><div className="auth-icon"><ShieldCheck size={24}/></div><div className="eyebrow">LOCAL BUSINESS WORKSPACE</div><h1>{authMode === "register" ? "Create your company" : "Welcome back"}</h1><p className="muted">{authMode === "register" ? "Set up your local ERP company and owner account." : "Sign in to access your business records."}</p><form className="form-stack" onSubmit={authenticate}>{authMode === "register" && <Field label="Company name" name="companyName" required placeholder="Sastha Infinite Enterprise"/>}<Field label="Email address" name="email" type="email" required placeholder="you@company.com"/><Field label="Password" name="password" type="password" required minLength={authMode === "register" ? 12 : 1} placeholder={authMode === "register" ? "At least 12 characters" : "Your password"}/>{authMode === "register" && <div className="hint">The first account becomes the company owner. Use a strong password and keep it private.</div>}<button className="primary-button full-width" disabled={authLoading}>{authLoading ? "Please wait…" : authMode === "register" ? "Create workspace" : "Sign in"}</button></form><div className="auth-switch">{authMode === "register" ? "Already registered?" : "First time setting up this ERP?"} <button onClick={() => setAuthMode(authMode === "register" ? "login" : "register")}>{authMode === "register" ? "Sign in" : "Create company"}</button></div><div className="auth-footer"><ShieldCheck size={14}/> Local database · Company-separated records</div></div>{notice && <Toast notice={notice} onClose={() => setNotice(null)}/>}</div>;

  const activeNav = NAV.find(n => n.name === active)!;
  return <div className="app-shell">
    <aside className={`sidebar ${mobileOpen ? "open" : ""}`}><div className="brand"><div className="brand-mark"><Boxes size={22}/></div><div><strong>SASTHA INFINITE</strong><small>BUSINESS ERP</small></div></div><div className="workspace"><span className="workspace-icon"><Building2 size={18}/></span><div className="workspace-copy"><strong>{session.company.name}</strong><small>{session.role.replaceAll("_"," ")}</small></div></div><div className="nav-label">WORKSPACE</div><nav>{NAV.map(({name,icon:Icon})=><button key={name} onClick={()=>navigate(name)} className={active===name?"nav-item active":"nav-item"}><Icon size={18}/><span>{name}</span></button>)}</nav><div className="sidebar-bottom"><ShieldCheck size={17}/><span>Company-separated workspace</span></div></aside>
    {mobileOpen && <button className="scrim" aria-label="Close menu" onClick={()=>setMobileOpen(false)}/>}
    <main className="main"><header className="topbar"><button className="mobile-menu" aria-label="Open menu" onClick={()=>setMobileOpen(v=>!v)}><Menu/></button><div className="breadcrumb">Workspace <span>/</span><strong>{active}</strong></div><div className="top-actions">{searchOpen && <input className="top-search" autoFocus placeholder="Search this module…" value={search} onChange={e=>setSearch(e.target.value)}/>}<button className="icon-button" aria-label="Search" onClick={()=>{setSearchOpen(v=>!v);setSearch("")}}><Search size={18}/></button><div className="notification-wrap"><button className="icon-button" aria-label="Notifications" onClick={()=>setNoticeOpen(v=>!v)}><Bell size={18}/>{notifications.length>0 && <i className="notification-dot"/>}</button>{noticeOpen && <div className="notification-menu"><div className="notification-title">Recent activity</div>{notifications.length ? notifications.slice(0,7).map(n=><div className="notification-item" key={`${n.id}${n.title}`}><b>{n.title}</b><span>{n.detail}</span><small>{dateTimeText(n.createdAt)}</small></div>) : <div className="empty-small">No recent activity yet.</div>}</div>}</div><div className="avatar" title={session.user.email}>{session.user.email.slice(0,2).toUpperCase()}</div><button className="icon-button logout-button" aria-label="Sign out" title="Sign out" onClick={logout}><LogOut size={17}/></button></div></header>
      <div className="content"><div className="page-heading"><div><div className="eyebrow">SASTHA INFINITE ENTERPRISE</div><h1>{active === "Overview" ? "Business overview" : active}</h1><p>{activeNav.description}. Company data is stored in your local PostgreSQL database.</p></div>{active !== "Overview" && active !== "Reports" && active !== "Subscription" && active !== "Settings" && <button className="primary-button" onClick={()=>active==="Sales"?openNew("salesDoc","INVOICE"):active==="Purchases"?openNew("purchaseDoc","PURCHASE_ORDER"):active==="Inventory"?openNew("product"):active==="Customers"?openNew("customer"):active==="Suppliers"?openNew("supplier"):openNew("expense")}><Plus size={17}/> {active === "Sales" ? "New sales document" : active === "Purchases" ? "New purchase document" : active === "Inventory" ? "Add product" : active === "Customers" ? "Add customer" : active === "Suppliers" ? "Add supplier" : "Add expense"}</button>}{active==="Settings" && <button className="primary-button" onClick={()=>openNew("settings")}><SettingsIcon size={16}/> Edit settings</button>}</div>
      {notice && <Toast notice={notice} onClose={()=>setNotice(null)}/>}
      {loading && <div className="loading-strip"><RefreshCw size={14} className="spin"/> Loading {active.toLowerCase()}…</div>}
      {active === "Overview" && <Overview data={dashboard} onNavigate={navigate} onQuick={openNew} onRefresh={()=>void loadModule("Overview")}/>}
      {active === "Customers" && <MasterTable title="Customer directory" rows={visibleRows ?? customers} kind="customers" onEdit={r=>openEdit("customer",r)} onArchive={r=>void archiveRecord("customers",r)} onExport={()=>exportCsv("customers",customers)} />}
      {active === "Suppliers" && <MasterTable title="Supplier directory" rows={visibleRows ?? suppliers} kind="suppliers" onEdit={r=>openEdit("supplier",r)} onArchive={r=>void archiveRecord("suppliers",r)} onExport={()=>exportCsv("suppliers",suppliers)} />}
      {active === "Inventory" && <InventoryPage products={visibleRows ?? products} warehouses={warehouses} movements={movements} onNewProduct={()=>openNew("product")} onNewWarehouse={()=>openNew("warehouse")} onAdjust={()=>openNew("stock")} onEdit={r=>openEdit("product",r)} onArchive={r=>void archiveRecord("products",r)} onExport={()=>exportCsv("inventory",products)} />}
      {active === "Sales" && <DocumentsPage kind="sales" rows={visibleRows ?? sales} warehouses={warehouses} onNew={type=>openNew("salesDoc",type)} onIssue={r=>void issueSales(r)} onVoid={r=>void (async()=>{if(window.confirm(`Void draft ${r.documentNo}?`)){try{await api(`/api/sales-documents/${r.id}/void`,{method:"POST"});pushNotice("success","Draft voided.");await loadModule("Sales");}catch(e){pushNotice("error",e instanceof Error?e.message:"Could not void document.");}}})()} onPrint={printSales} onExport={()=>exportCsv("sales-documents",sales)} />}
      {active === "Purchases" && <DocumentsPage kind="purchases" rows={visibleRows ?? purchases} warehouses={warehouses} onNew={type=>openNew("purchaseDoc",type)} onIssue={r=>void issuePurchase(r)} onReceive={r=>void receiveOrder(r)} onExport={()=>exportCsv("purchase-documents",purchases)} />}
      {active === "Finance" && <FinancePage receipts={receipts} payments={payments} expenses={expenses} onNewReceipt={()=>openNew("receipt")} onNewPayment={()=>openNew("payment")} onNewExpense={()=>openNew("expense")} onExport={()=>exportCsv("finance",[...receipts,...payments,...expenses])} />}
      {active === "Reports" && <ReportsPage report={report} onExport={exportCsv} onRefresh={()=>void loadModule("Reports")}/>}
      {active === "Settings" && <SettingsPage settings={settings} warehouses={warehouses} logs={movements} onEdit={()=>openNew("settings")} onAddWarehouse={()=>openNew("warehouse")} onExport={()=>exportCsv("audit-log",movements)} />}
      {active === "Subscription" && <SubscriptionPage company={session.company} email={session.user.email} role={session.role} settings={settings} onRefresh={()=>loadModule("Subscription")} onNotice={pushNotice} />}
      <footer>© {new Date().getFullYear()} Sastha Infinite Enterprise <span>Local ERP · {session.company.name}</span></footer></div>
    </main>
    {modal && <Modal title={modalTitle(modal,editRow)} onClose={()=>{setModal(null);setEditRow(null)}}><form className="form-stack" onSubmit={submitForm}>
      {(modal === "customer" || modal === "supplier") && <><Field label="Name / company name" name="name" defaultValue={editRow?.name} required/><div className="form-grid"><Field label="Email" name="email" type="email" defaultValue={editRow?.email}/><Field label="Phone" name="phone" defaultValue={editRow?.phone}/><Field label="TIN" name="tin" defaultValue={editRow?.tin}/><Field label="Registration no." name="registrationNo" defaultValue={editRow?.registrationNo}/></div><Field label="Address" name="address" defaultValue={editRow?.address?.text ?? ""} placeholder="Billing or business address"/></>}
      {modal === "product" && <><div className="form-grid"><Field label="SKU / product code" name="sku" defaultValue={editRow?.sku} required/><Field label="Product name" name="name" defaultValue={editRow?.name} required/><Field label="Barcode" name="barcode" defaultValue={editRow?.barcode}/><Field label="Unit code" name="unitCode" defaultValue={editRow?.unitCode ?? "UNIT"}/><Field label="Selling price (RM)" name="unitPrice" type="number" step="0.01" min="0" defaultValue={editRow?.unitPrice ?? 0} required/><Field label="Cost price (RM)" name="unitCost" type="number" step="0.01" min="0" defaultValue={editRow?.unitCost ?? 0} required/></div><Field label="Description" name="description" defaultValue={editRow?.description}/>{editRow && <p className="hint">Current stock: {Number(editRow.stockOnHand ?? 0).toLocaleString()} — use Stock adjustment to change quantity.</p>}</>}
      {modal === "warehouse" && <div className="form-grid"><Field label="Warehouse code" name="code" required placeholder="MAIN-2"/><Field label="Warehouse name" name="name" required placeholder="Secondary warehouse"/></div>}
      {(modal === "salesDoc" || modal === "purchaseDoc") && <><div className="form-grid"><label className="field"><span>Document type</span><select value={docType} onChange={e=>setDocType(e.target.value)}>{(modal === "salesDoc" ? [{v:"QUOTATION",t:"Quotation"},{v:"SALES_ORDER",t:"Sales order"},{v:"INVOICE",t:"Sales invoice"},{v:"CREDIT_NOTE",t:"Credit note"}] : [{v:"PURCHASE_ORDER",t:"Purchase order"},{v:"SUPPLIER_INVOICE",t:"Supplier invoice"}]).map(o=><option value={o.v} key={o.v}>{o.t}</option>)}</select></label><Field label="Document no. (optional)" name="documentNo" placeholder="Auto-generated if blank"/></div>{modal === "salesDoc" ? <label className="field"><span>Customer</span><select name="customerId" required defaultValue=""><option value="" disabled>Select a customer</option>{customers.filter(x=>x.active).map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select></label> : <label className="field"><span>Supplier</span><select name="supplierId" required defaultValue=""><option value="" disabled>Select a supplier</option>{suppliers.filter(x=>x.active).map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select></label>}<div className="line-items-head"><b>Line items</b><button type="button" className="text-button" onClick={()=>setDocLines(prev=>[...prev,{productId:"",description:"",quantity:"1",unitPrice:"0"}])}><Plus size={14}/> Add line</button></div>{docLines.map((line,i)=><div className="line-editor" key={i}><label className="field"><span>Product (optional)</span><select value={line.productId} onChange={e=>{const product=products.find(p=>p.id===e.target.value);setDocLines(prev=>prev.map((x,j)=>j===i?{...x,productId:e.target.value,description:product?.name??x.description,unitPrice:String(modal==="salesDoc"?product?.unitPrice??0:product?.unitCost??0)}:x))}}><option value="">Free-text item</option>{products.filter(p=>p.status==="ACTIVE").map(p=><option key={p.id} value={p.id}>{p.sku} — {p.name}</option>)}</select></label><Field label="Description" value={line.description} required onChange={v=>setDocLines(prev=>prev.map((x,j)=>j===i?{...x,description:v}:x))}/><div className="form-grid compact"><Field label="Qty" type="number" value={line.quantity} required min="0.0001" step="0.0001" onChange={v=>setDocLines(prev=>prev.map((x,j)=>j===i?{...x,quantity:v}:x))}/><Field label={modal === "salesDoc" ? "Unit price (RM)" : "Unit cost (RM)"} type="number" value={line.unitPrice} required min="0" step="0.0001" onChange={v=>setDocLines(prev=>prev.map((x,j)=>j===i?{...x,unitPrice:v}:x))}/></div>{docLines.length>1 && <button type="button" className="icon-danger line-remove" aria-label="Remove line" onClick={()=>setDocLines(prev=>prev.filter((_,j)=>j!==i))}><X size={15}/></button>}</div>)}<div className="form-grid"><Field label={modal === "salesDoc" ? "Discount (RM)" : "Discount not applied"} name="discount" type="number" min="0" step="0.01" defaultValue="0" disabled={modal !== "salesDoc"}/><Field label="Tax rate (%)" name="taxRate" type="number" min="0" max="100" step="0.01" defaultValue="0"/></div><div className="doc-estimate">Subtotal estimate <strong>{money(docLines.reduce((s,l)=>s+Number(l.quantity||0)*Number(l.unitPrice||0),0))}</strong></div><div className="hint">Stock is posted when an invoice is issued, not when a draft is saved. The tax rate is entered manually; confirm tax treatment with your accountant.</div></>}
      {modal === "stock" && <><div className="form-grid"><label className="field"><span>Product</span><select name="productId" defaultValue="" required><option value="" disabled>Select product</option>{products.filter(p=>p.status==="ACTIVE").map(p=><option key={p.id} value={p.id}>{p.sku} — {p.name} (stock {p.stockOnHand})</option>)}</select></label><label className="field"><span>Warehouse</span><select name="warehouseId" defaultValue={warehouses[0]?.id??""} required>{warehouses.map(w=><option key={w.id} value={w.id}>{w.name}</option>)}</select></label><label className="field"><span>Movement reason</span><select name="type"><option value="ADJUSTMENT">Stock adjustment</option><option value="OPENING">Opening stock</option><option value="RECEIPT">Stock receipt</option><option value="RETURN_IN">Return in</option><option value="RETURN_OUT">Return out</option></select></label><label className="field"><span>Direction</span><select name="direction"><option value="increase">Increase stock</option><option value="decrease">Decrease stock</option></select></label><Field label="Quantity" name="quantity" type="number" min="0.0001" step="0.0001" required/><Field label="Unit cost (RM, optional)" name="unitCost" type="number" min="0" step="0.0001"/><Field label="Reason / reference" name="reason" required placeholder="Opening count, damaged goods, etc."/></div><div className="hint">Stock adjustments are recorded in the movement ledger. Negative stock is blocked.</div></>}
      {modal === "receipt" && <><label className="field"><span>Customer</span><select name="customerId" required defaultValue=""><option value="" disabled>Select customer</option>{customers.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="field"><span>Invoice (optional)</span><select name="documentId" defaultValue=""><option value="">Unallocated receipt</option>{sales.filter(d=>d.type==="INVOICE"&&d.status==="ISSUED"&&Number(d.balance)>0).map(d=><option key={d.id} value={d.id}>{d.documentNo} · {d.customer?.name} · balance {money(d.balance)}</option>)}</select></label><div className="form-grid"><Field label="Amount (RM)" name="amount" type="number" min="0.01" step="0.01" required/><label className="field"><span>Method</span><select name="method"><option>Bank transfer</option><option>Cash</option><option>Cheque</option><option>Card</option><option>Other</option></select></label></div><Field label="Reference" name="reference"/><Field label="Note" name="note"/></>}
      {modal === "payment" && <><label className="field"><span>Supplier</span><select name="supplierId" required defaultValue=""><option value="" disabled>Select supplier</option>{suppliers.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label className="field"><span>Supplier invoice (optional)</span><select name="documentId" defaultValue=""><option value="">Unallocated payment</option>{purchases.filter(d=>d.type==="SUPPLIER_INVOICE"&&d.status==="ISSUED"&&Number(d.balance)>0).map(d=><option key={d.id} value={d.id}>{d.documentNo} · {d.supplier?.name} · balance {money(d.balance)}</option>)}</select></label><div className="form-grid"><Field label="Amount (RM)" name="amount" type="number" min="0.01" step="0.01" required/><label className="field"><span>Method</span><select name="method"><option>Bank transfer</option><option>Cash</option><option>Cheque</option><option>Card</option><option>Other</option></select></label></div><Field label="Reference" name="reference"/><Field label="Note" name="note"/></>}
      {modal === "expense" && <><div className="form-grid"><label className="field"><span>Category</span><select name="category"><option>Office</option><option>Transport</option><option>Utilities</option><option>Rent</option><option>Staff</option><option>Marketing</option><option>Maintenance</option><option>Other</option></select></label><Field label="Description" name="description" required/><Field label="Amount (RM)" name="amount" type="number" min="0.01" step="0.01" required/><label className="field"><span>Payment method</span><select name="method"><option>Bank transfer</option><option>Cash</option><option>Card</option><option>Cheque</option><option>Other</option></select></label></div><Field label="Reference" name="reference"/><Field label="Notes" name="notes"/></>}
      {modal === "settings" && <><div className="form-grid"><Field label="Company name" name="name" defaultValue={settings?.name ?? session.company.name} required/><Field label="Registration no." name="registrationNo" defaultValue={settings?.registrationNo ?? ""}/><label className="field"><span>Currency</span><select name="currency" defaultValue={settings?.settings?.currency ?? "MYR"}><option value="MYR">MYR — Malaysian Ringgit</option><option value="SGD">SGD — Singapore Dollar</option><option value="USD">USD — US Dollar</option></select></label><Field label="Timezone" name="timezone" defaultValue={settings?.settings?.timezone ?? "Asia/Kuala_Lumpur"} required/><Field label="Invoice prefix" name="invoicePrefix" defaultValue={settings?.settings?.invoicePrefix ?? "INV"} required/></div><div className="hint">Company settings are saved to PostgreSQL. This local version does not yet apply SST/e-Invoice compliance rules automatically.</div></>}
      <div className="modal-actions"><button type="button" className="secondary-button" onClick={()=>{setModal(null);setEditRow(null)}}>Cancel</button><button className="primary-button" disabled={busy}>{busy ? "Saving…" : editRow ? "Save changes" : "Save record"}</button></div>
    </form></Modal>}
  </div>;
}

function Field({ label, name, type="text", required=false, placeholder, defaultValue, value, onChange, disabled=false, min, max, step, minLength }: { label:string; name?:string; type?:string; required?:boolean; placeholder?:string; defaultValue?:string|number; value?:string; onChange?:(value:string)=>void; disabled?:boolean; min?:string; max?:string; step?:string; minLength?:number }) {
  return <label className="field"><span>{label}{required && <i> *</i>}</span><input name={name} type={type} required={required} placeholder={placeholder} defaultValue={onChange ? undefined : defaultValue} value={onChange ? value : undefined} onChange={onChange ? e=>onChange(e.target.value) : undefined} disabled={disabled} min={min} max={max} step={step} minLength={minLength}/></label>;
}
function Modal({ title, children, onClose }: { title:string; children:any; onClose:()=>void }) { return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal-card"><div className="modal-heading"><div><h2>{title}</h2><p>Fields marked with * are required.</p></div><button className="icon-button" aria-label="Close" onClick={onClose}><X/></button></div>{children}</div></div>; }
function Toast({ notice, onClose }: { notice:{type:string;text:string}; onClose:()=>void }) { return <div className={`toast toast-${notice.type}`}><span>{notice.type==="error"?<CircleAlert size={18}/>:notice.type==="success"?<Check size={18}/>:<Activity size={18}/>}</span><div>{notice.text}</div><button aria-label="Close notification" onClick={onClose}><X size={15}/></button></div>; }
function modalTitle(modal:string, row:Row|null) { const titles:Record<string,string>={customer:row?"Edit customer":"Add customer",supplier:row?"Edit supplier":"Add supplier",product:row?"Edit product":"Add product",warehouse:"Add warehouse",salesDoc:"Create sales document",purchaseDoc:"Create purchase document",stock:"Record stock movement",receipt:"Record customer receipt",payment:"Record supplier payment",expense:"Record expense",settings:"Company settings"}; return titles[modal]??"Record"; }
function Empty({ title, detail, action, onAction }: { title:string; detail:string; action?:string; onAction?:()=>void }) { return <div className="empty-state"><div className="empty-icon"><ClipboardList size={24}/></div><b>{title}</b><p>{detail}</p>{action&&onAction&&<button className="secondary-button" onClick={onAction}><Plus size={15}/>{action}</button>}</div>; }
function TableToolbar({ title, count, onExport }: { title:string;count:number;onExport:()=>void }) { return <div className="panel-heading table-toolbar"><div><h2>{title}</h2><p>{count} record{count===1?"":"s"}</p></div><button className="secondary-button small" onClick={onExport}><ArrowDownToLine size={15}/> Export CSV</button></div>; }
function Overview({ data, onNavigate, onQuick, onRefresh }: { data:Row|null;onNavigate:(p:Module)=>void;onQuick:(kind:string,type?:string)=>void;onRefresh:()=>void }) {
  const d=data??{}; return <><div className="notice"><div className="notice-icon"><ShieldCheck size={19}/></div><div><strong>Local ERP workspace</strong><p>Records are saved in your PostgreSQL database. Use sample data until your workflows and reports have been verified.</p></div><button className="icon-button" onClick={onRefresh} aria-label="Refresh dashboard"><RefreshCw size={16}/></button></div><section className="metric-grid"><Metric title="Sales this month" value={money(d.salesThisMonth)} change={`${d.invoiceCount??0} issued invoices`} icon={<ShoppingCart/>} onClick={()=>onNavigate("Sales")}/><Metric title="Purchases this month" value={money(d.purchasesThisMonth)} change={`${d.purchaseInvoiceCount??0} supplier invoices`} icon={<Truck/>} onClick={()=>onNavigate("Purchases")}/><Metric title="Active products" value={Number(d.stockItems??0).toLocaleString()} change="Product catalogue" icon={<Package/>} onClick={()=>onNavigate("Inventory")}/><Metric title="Receivables outstanding" value={money(d.outstanding)} change="Issued invoices less receipts" icon={<CreditCard/>} onClick={()=>onNavigate("Finance")}/></section><section className="metric-grid secondary-metrics"><Metric title="Customers" value={String(d.customers??0)} change="Active customer records" icon={<Users/>} onClick={()=>onNavigate("Customers")}/><Metric title="Suppliers" value={String(d.suppliers??0)} change="Active supplier records" icon={<Building2/>} onClick={()=>onNavigate("Suppliers")}/><Metric title="Expenses this month" value={money(d.expensesThisMonth)} change="Recorded operating expenses" icon={<Wallet/>} onClick={()=>onNavigate("Finance")}/><Metric title="Database" value="Connected" change="Dashboard loaded from API" icon={<ShieldCheck/>} onClick={onRefresh}/></section><section className="lower-grid"><div className="panel"><div className="panel-heading"><div><h2>Get started</h2><p>Build your workspace in a safe sequence</p></div><span className="status status-green">Local</span></div><div className="setup-list"><Setup n="01" title="Set company details" desc="Name, currency and invoice prefix" onClick={()=>onNavigate("Settings")}/><Setup n="02" title="Add products and opening stock" desc="Create SKUs, prices and initial quantities" onClick={()=>onNavigate("Inventory")}/><Setup n="03" title="Add customers and suppliers" desc="Prepare master records before transactions" onClick={()=>onNavigate("Customers")}/><Setup n="04" title="Create and issue documents" desc="Use drafts first, then issue when verified" onClick={()=>onNavigate("Sales")}/></div></div><div className="panel quick-panel"><div className="panel-heading"><div><h2>Quick actions</h2><p>Common business tasks</p></div></div>{[{i:FilePlus2,title:"New quotation",desc:"Prepare a customer quote",run:()=>onQuick("salesDoc","QUOTATION")},{i:ShoppingCart,title:"Sales invoice",desc:"Record a customer sale",run:()=>onQuick("salesDoc","INVOICE")},{i:Truck,title:"Purchase order",desc:"Order stock from a supplier",run:()=>onQuick("purchaseDoc","PURCHASE_ORDER")},{i:Boxes,title:"Stock adjustment",desc:"Record a verified stock change",run:()=>onQuick("stock")}].map(({i:Icon,title,desc,run})=><button className="quick-action" key={title} onClick={run}><span className="quick-icon"><Icon size={18}/></span><span className="quick-copy"><strong>{title}</strong><small>{desc}</small></span><ArrowUpRight size={16}/></button>)}</div></section><div className="lower-grid"><div className="panel"><div className="panel-heading"><div><h2>Recent sales documents</h2><p>Latest transactions</p></div><button className="text-button" onClick={()=>onNavigate("Sales")}>View all <ArrowUpRight size={14}/></button></div>{d.recentSales?.length?<div className="compact-list">{d.recentSales.map((r:Row)=><div key={r.id} className="compact-row"><div className="record-icon"><FileText size={16}/></div><div className="compact-main"><b>{r.documentNo}</b><small>{r.customer?.name} · {r.type.replaceAll("_"," ")}</small></div><div className="compact-end"><b>{money(r.grandTotal)}</b><span className={statusClass(r.status)}>{r.status}</span></div></div>)}</div>:<p className="muted pad">No sales documents yet.</p>}</div><div className="panel"><div className="panel-heading"><div><h2>Recent stock movements</h2><p>Inventory activity ledger</p></div><button className="text-button" onClick={()=>onNavigate("Inventory")}>View all <ArrowUpRight size={14}/></button></div>{d.recentMovements?.length?<div className="compact-list">{d.recentMovements.map((r:Row)=><div key={r.id} className="compact-row"><div className="record-icon"><Package size={16}/></div><div className="compact-main"><b>{r.product?.name}</b><small>{r.type.replaceAll("_"," ")} · {r.warehouse?.name}</small></div><div className="compact-end"><b>{Number(r.quantityDelta)>0?"+":""}{Number(r.quantityDelta).toLocaleString()}</b><small>{dateText(r.createdAt)}</small></div></div>)}</div>:<p className="muted pad">No stock movements recorded.</p>}</div></div></>;
}
function Metric({title,value,change,icon,onClick}:{title:string;value:string;change:string;icon:any;onClick:()=>void}) { return <button className="metric-card" onClick={onClick}><div className="metric-top"><span>{title}</span><span className="metric-icon">{icon}</span></div><strong className="metric-value">{value}</strong><small>{change}</small></button>; }
function Setup({n,title,desc,onClick}:{n:string;title:string;desc:string;onClick:()=>void}) { return <button className="setup-item" onClick={onClick}><span className="setup-number">{n}</span><div><strong>{title}</strong><small>{desc}</small></div><span className="setup-state">Open <ArrowUpRight size={13}/></span></button>; }
function MasterTable({title,rows,kind,onEdit,onArchive,onExport}:{title:string;rows:Row[];kind:"customers"|"suppliers";onEdit:(r:Row)=>void;onArchive:(r:Row)=>void;onExport:()=>void}) {
  return <div className="panel"><TableToolbar title={title} count={rows.length} onExport={onExport}/>{rows.length===0?<Empty title="No records yet" detail={`Add your first ${kind.slice(0,-1)} to start using this module.`}/>:<div className="table-scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>TIN</th><th>Status</th><th className="right">Actions</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><b>{r.name}</b><small className="cell-sub">{r.registrationNo||r.address?.text||"—"}</small></td><td>{r.email||"—"}</td><td>{r.phone||"—"}</td><td>{r.tin||"—"}</td><td><span className={statusClass(r.active?"ACTIVE":"ARCHIVED")}>{r.active?"Active":"Archived"}</span></td><td className="actions-cell"><button className="table-icon" title="Edit" onClick={()=>onEdit(r)}><Pencil size={15}/></button>{r.active&&<button className="table-icon danger" title="Archive" onClick={()=>onArchive(r)}><Archive size={15}/></button>}</td></tr>)}</tbody></table></div>}</div>;
}
function InventoryPage({products,warehouses,movements,onNewProduct,onNewWarehouse,onAdjust,onEdit,onArchive,onExport}:{products:Row[];warehouses:Row[];movements:Row[];onNewProduct:()=>void;onNewWarehouse:()=>void;onAdjust:()=>void;onEdit:(r:Row)=>void;onArchive:(r:Row)=>void;onExport:()=>void}) {
  return <><div className="mini-actions"><button className="secondary-button" onClick={onNewWarehouse}><Building2 size={15}/> Add warehouse</button><button className="secondary-button" onClick={onAdjust}><Activity size={15}/> Stock adjustment</button><button className="secondary-button" onClick={onExport}><ArrowDownToLine size={15}/> Export inventory</button></div><div className="panel"><TableToolbar title="Products & stock on hand" count={products.length} onExport={onExport}/>{products.length===0?<Empty title="No products yet" detail="Add your product catalogue, then enter opening stock." action="Add product" onAction={onNewProduct}/>:<div className="table-scroll"><table><thead><tr><th>SKU / Barcode</th><th>Product</th><th>Cost</th><th>Selling price</th><th className="right">Stock on hand</th><th>Status</th><th className="right">Actions</th></tr></thead><tbody>{products.map(p=><tr key={p.id}><td><b>{p.sku}</b><small className="cell-sub">{p.barcode||"No barcode"}</small></td><td>{p.name}<small className="cell-sub">{p.description||p.unitCode}</small></td><td>{money(p.unitCost)}</td><td>{money(p.unitPrice)}</td><td className="right"><b className={Number(p.stockOnHand)<=0?"stock-zero":""}>{Number(p.stockOnHand??0).toLocaleString()}</b></td><td><span className={statusClass(p.status)}>{p.status}</span></td><td className="actions-cell"><button className="table-icon" title="Edit" onClick={()=>onEdit(p)}><Pencil size={15}/></button>{p.status==="ACTIVE"&&<button className="table-icon danger" title="Archive" onClick={()=>onArchive(p)}><Archive size={15}/></button>}</td></tr>)}</tbody></table></div>}<div className="table-bottom"><span>{warehouses.length} active warehouse(s)</span><button className="text-button" onClick={onNewProduct}><Plus size={14}/> Add product</button></div></div><div className="panel mt-20"><TableToolbar title="Stock movement ledger" count={movements.length} onExport={()=>{const csvRows=movements.map(m=>({date:m.createdAt,type:m.type,sku:m.product?.sku,product:m.product?.name,warehouse:m.warehouse?.name,quantityDelta:m.quantityDelta,reason:m.reason,sourceType:m.sourceType}));if(!csvRows.length)return; const blob=new Blob(["\ufeff"+Object.keys(csvRows[0]).join(",")+"\r\n"+csvRows.map(r=>Object.values(r).map(v=>`"${String(v??"").replace(/"/g,'""')}"`).join(",")).join("\r\n")],{type:"text/csv"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="stock-movements.csv";a.click();URL.revokeObjectURL(url);}}/>{movements.length===0?<Empty title="No stock movements" detail="Opening stock, receipts, sales and adjustments will appear here."/>:<div className="table-scroll"><table><thead><tr><th>Date</th><th>Product</th><th>Warehouse</th><th>Movement</th><th>Qty change</th><th>Reason</th></tr></thead><tbody>{movements.map(m=><tr key={m.id}><td>{dateText(m.createdAt)}</td><td><b>{m.product?.name||m.action||"—"}</b><small className="cell-sub">{m.product?.sku||m.entityType||""}</small></td><td>{m.warehouse?.name||"—"}</td><td>{m.type||m.action}</td><td className={Number(m.quantityDelta)<0?"text-red":"text-green"}>{m.quantityDelta==null?"—":`${Number(m.quantityDelta)>0?"+":""}${m.quantityDelta}`}</td><td>{m.reason||m.entityId||"—"}</td></tr>)}</tbody></table></div>}</div></>;
}
function DocumentsPage({kind,rows,warehouses,onNew,onIssue,onVoid,onPrint,onReceive,onExport}:{kind:"sales"|"purchases";rows:Row[];warehouses:Row[];onNew:(t:string)=>void;onIssue:(r:Row)=>void;onVoid?:(r:Row)=>void;onPrint?:(r:Row)=>void;onReceive?:(r:Row)=>void;onExport:()=>void}) {
  const sales=kind==="sales"; return <><div className="mini-actions">{(sales?[{label:"Quotation",type:"QUOTATION"},{label:"Sales order",type:"SALES_ORDER"},{label:"Sales invoice",type:"INVOICE"},{label:"Credit note",type:"CREDIT_NOTE"}]:[{label:"Purchase order",type:"PURCHASE_ORDER"},{label:"Supplier invoice",type:"SUPPLIER_INVOICE"}]).map(t=><button key={t.type} className="secondary-button" onClick={()=>onNew(t.type)}><Plus size={14}/>{t.label}</button>)}<button className="secondary-button" onClick={onExport}><ArrowDownToLine size={15}/> Export CSV</button></div><div className="panel"><TableToolbar title={sales?"Sales documents":"Purchase documents"} count={rows.length} onExport={onExport}/>{rows.length===0?<Empty title={sales?"No sales documents":"No purchase documents"} detail={sales?"Create a quotation, sales order, invoice or credit note.":"Create a purchase order or supplier invoice."} action={sales?"Create quotation":"Create purchase order"} onAction={()=>onNew(sales?"QUOTATION":"PURCHASE_ORDER")}/>:<div className="table-scroll"><table><thead><tr><th>Document</th><th>{sales?"Customer":"Supplier"}</th><th>Type</th><th>Date</th><th className="right">Total</th><th>Status</th><th className="right">Actions</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><b>{r.documentNo}</b><small className="cell-sub">{r.lines?.length??0} line item(s)</small></td><td>{sales?r.customer?.name:r.supplier?.name}</td><td>{String(r.type).replaceAll("_"," ")}</td><td>{dateText(r.issuedAt||r.createdAt)}</td><td className="right"><b>{money(r.grandTotal)}</b>{(r.paidAmount??0)>0&&<small className="cell-sub">Paid {money(r.paidAmount)}</small>}</td><td><span className={statusClass(r.status)}>{r.status}</span></td><td className="actions-cell">{sales&&onPrint&&<button className="table-icon" title="Print / Save as PDF" onClick={()=>onPrint(r)}><Printer size={15}/></button>}{r.status==="DRAFT"&&<button className="table-button" onClick={()=>onIssue(r)}>Issue</button>}{sales&&r.status==="DRAFT"&&onVoid&&<button className="table-icon danger" title="Void draft" onClick={()=>onVoid(r)}><X size={15}/></button>}{!sales&&r.type==="PURCHASE_ORDER"&&r.status==="ISSUED"&&onReceive&&<button className="table-button" onClick={()=>onReceive(r)}>Receive</button>}{!sales&&r.status==="DRAFT"&&!onIssue?null:null}</td></tr>)}</tbody></table></div>}<div className="table-bottom"><span>Stock posts only when an invoice is issued or a purchase order is received.</span><span>{warehouses.length} warehouse(s)</span></div></div></>;
}
function FinancePage({receipts,payments,expenses,onNewReceipt,onNewPayment,onNewExpense,onExport}:{receipts:Row[];payments:Row[];expenses:Row[];onNewReceipt:()=>void;onNewPayment:()=>void;onNewExpense:()=>void;onExport:()=>void}) {
  const receiptTotal=receipts.reduce((s,r)=>s+Number(r.amount),0), paymentTotal=payments.reduce((s,r)=>s+Number(r.amount),0), expenseTotal=expenses.reduce((s,r)=>s+Number(r.amount),0);
  return <><div className="metric-grid three"><Metric title="Customer receipts" value={money(receiptTotal)} change={`${receipts.length} record(s), all dates`} icon={<ArrowDownToLine/>} onClick={onNewReceipt}/><Metric title="Supplier payments" value={money(paymentTotal)} change={`${payments.length} record(s), all dates`} icon={<ArrowUpRight/>} onClick={onNewPayment}/><Metric title="Expenses" value={money(expenseTotal)} change={`${expenses.length} record(s), all dates`} icon={<Wallet/>} onClick={onNewExpense}/></div><div className="mini-actions"><button className="secondary-button" onClick={onNewReceipt}><Plus size={15}/> Customer receipt</button><button className="secondary-button" onClick={onNewPayment}><Plus size={15}/> Supplier payment</button><button className="secondary-button" onClick={onNewExpense}><Plus size={15}/> Expense</button><button className="secondary-button" onClick={onExport}><ArrowDownToLine size={15}/> Export finance CSV</button></div><div className="panel"><TableToolbar title="Customer receipts" count={receipts.length} onExport={onExport}/>{receipts.length===0?<Empty title="No receipts recorded" detail="Record customer cash or bank receipts here." action="Record receipt" onAction={onNewReceipt}/>:<div className="table-scroll"><table><thead><tr><th>Receipt no.</th><th>Customer</th><th>Invoice</th><th>Date</th><th>Method</th><th className="right">Amount</th></tr></thead><tbody>{receipts.map(r=><tr key={r.id}><td><b>{r.receiptNo}</b></td><td>{r.customer?.name}</td><td>{r.document?.documentNo||"Unallocated"}</td><td>{dateText(r.paymentDate)}</td><td>{r.method}</td><td className="right"><b>{money(r.amount)}</b></td></tr>)}</tbody></table></div>}</div><div className="panel mt-20"><TableToolbar title="Supplier payments" count={payments.length} onExport={onExport}/>{payments.length===0?<Empty title="No supplier payments" detail="Record payments against supplier invoices." action="Record payment" onAction={onNewPayment}/>:<div className="table-scroll"><table><thead><tr><th>Payment no.</th><th>Supplier</th><th>Supplier invoice</th><th>Date</th><th>Method</th><th className="right">Amount</th></tr></thead><tbody>{payments.map(r=><tr key={r.id}><td><b>{r.paymentNo}</b></td><td>{r.supplier?.name}</td><td>{r.document?.documentNo||"Unallocated"}</td><td>{dateText(r.paymentDate)}</td><td>{r.method}</td><td className="right"><b>{money(r.amount)}</b></td></tr>)}</tbody></table></div>}</div><div className="panel mt-20"><TableToolbar title="Operating expenses" count={expenses.length} onExport={onExport}/>{expenses.length===0?<Empty title="No expenses recorded" detail="Track rent, utilities, transport and other business expenses." action="Add expense" onAction={onNewExpense}/>:<div className="table-scroll"><table><thead><tr><th>Date</th><th>Category</th><th>Description</th><th>Method</th><th>Reference</th><th className="right">Amount</th></tr></thead><tbody>{expenses.map(r=><tr key={r.id}><td>{dateText(r.expenseDate)}</td><td>{r.category}</td><td><b>{r.description}</b></td><td>{r.method}</td><td>{r.reference||"—"}</td><td className="right"><b>{money(r.amount)}</b></td></tr>)}</tbody></table></div>}</div><p className="hint page-hint">This finance module records cash movement and operational expenses, but it is not yet a statutory double-entry general ledger. Reconcile these reports before using for statutory accounts.</p></>;
}
function ReportsPage({report,onExport,onRefresh}:{report:Row|null;onExport:(name:string,rows:Row[])=>void;onRefresh:()=>void}) {
  const totals=report?.totals??{}; return <><div className="notice"><div className="notice-icon"><ChartNoAxesCombined size={18}/></div><div><b>Operational reports</b><p>Current report uses this calendar year through today. CSV files can be opened in Excel.</p></div><button className="icon-button" onClick={onRefresh}><RefreshCw size={15}/></button></div><div className="metric-grid three"><Metric title="Issued sales invoices" value={money(totals.sales)} change={`${report?.salesDocs?.length??0} invoice(s)`} icon={<ShoppingCart/>} onClick={()=>onExport("sales-invoices",report?.salesDocs??[])}/><Metric title="Supplier invoices" value={money(totals.purchases)} change={`${report?.purchaseDocs?.length??0} invoice(s)`} icon={<Truck/>} onClick={()=>onExport("supplier-invoices",report?.purchaseDocs??[])}/><Metric title="Cash movement (net)" value={money(totals.netCashMovement)} change="Receipts − payments − expenses" icon={<Banknote/>} onClick={()=>onExport("cash-movement",[...(report?.receipts??[]),...(report?.payments??[]),...(report?.expenses??[])])}/></div><div className="report-grid"><ReportCard title="Sales invoices" count={report?.salesDocs?.length??0} value={money(totals.sales)} onClick={()=>onExport("sales-invoices",report?.salesDocs??[])}/><ReportCard title="Customer receipts" count={report?.receipts?.length??0} value={money(totals.receipts)} onClick={()=>onExport("customer-receipts",report?.receipts??[])}/><ReportCard title="Supplier payments" count={report?.payments?.length??0} value={money(totals.supplierPayments)} onClick={()=>onExport("supplier-payments",report?.payments??[])}/><ReportCard title="Expenses" count={report?.expenses?.length??0} value={money(totals.expenses)} onClick={()=>onExport("expenses",report?.expenses??[])}/></div><div className="panel mt-20"><TableToolbar title="Inventory valuation preview" count={report?.products?.length??0} onExport={()=>onExport("inventory-valuation",(report?.products??[]).map((p:Row)=>({...p,stockValue:Number(p.stockOnHand??0)*Number(p.unitCost??0)})))}/>{!report?.products?.length?<Empty title="No product records" detail="Add products to see stock balances and inventory value."/>:<div className="table-scroll"><table><thead><tr><th>SKU</th><th>Product</th><th className="right">Stock</th><th className="right">Unit cost</th><th className="right">Estimated value</th></tr></thead><tbody>{report.products.map((p:Row)=><tr key={p.id}><td>{p.sku}</td><td>{p.name}</td><td className="right">{Number(p.stockOnHand).toLocaleString()}</td><td className="right">{money(p.unitCost)}</td><td className="right"><b>{money(Number(p.stockOnHand)*Number(p.unitCost))}</b></td></tr>)}</tbody></table></div>}</div><p className="hint page-hint">Reports are operational summaries, not audited financial statements. Confirm inventory valuation method, tax, statutory reporting and period-close rules with your accountant.</p></>;
}
function ReportCard({title,count,value,onClick}:{title:string;count:number;value:string;onClick:()=>void}) { return <button className="report-card" onClick={onClick}><span>{title}</span><strong>{value}</strong><small>{count} record(s)</small><ArrowDownToLine size={16}/></button>; }
function SettingsPage({settings,warehouses,logs,onEdit,onAddWarehouse,onExport}:{settings:Row|null;warehouses:Row[];logs:Row[];onEdit:()=>void;onAddWarehouse:()=>void;onExport:()=>void}) { return <><div className="settings-grid"><div className="panel"><div className="panel-heading"><div><h2>Company profile</h2><p>Used on your workspace and document headers</p></div><button className="secondary-button small" onClick={onEdit}><Pencil size={14}/> Edit</button></div><div className="profile-card"><div className="profile-mark"><Building2 size={24}/></div><div><h3>{settings?.name||"Company name not configured"}</h3><p>{settings?.registrationNo||"No registration number"}</p></div></div><div className="settings-rows"><SettingsRow label="Currency" value={`${settings?.settings?.currency??"MYR"} — Malaysian Ringgit`}/><SettingsRow label="Timezone" value={settings?.settings?.timezone??"Asia/Kuala_Lumpur"}/><SettingsRow label="Invoice prefix" value={settings?.settings?.invoicePrefix??"INV"}/><SettingsRow label="Database" value="PostgreSQL · Local Docker"/><SettingsRow label="App API" value={API}/></div></div><div className="panel"><div className="panel-heading"><div><h2>Warehouses</h2><p>Stock locations</p></div><button className="secondary-button small" onClick={onAddWarehouse}><Plus size={14}/> Add</button></div>{warehouses.length===0?<Empty title="No warehouse" detail="Create at least one warehouse before posting stock." action="Add warehouse" onAction={onAddWarehouse}/>:warehouses.map(w=><div className="warehouse-row" key={w.id}><div className="record-icon"><Building2 size={16}/></div><div><b>{w.name}</b><small>{w.code}</small></div><span className={statusClass(w.active?"ACTIVE":"ARCHIVED")}>{w.active?"Active":"Inactive"}</span></div>)}</div></div><div className="panel mt-20"><TableToolbar title="Recent audit activity" count={logs.length} onExport={onExport}/>{logs.length===0?<Empty title="No audit activity" detail="Important record changes will be listed here."/>:<div className="table-scroll"><table><thead><tr><th>When</th><th>Action</th><th>Record type</th><th>Record ID</th></tr></thead><tbody>{logs.map(r=><tr key={r.id}><td>{dateTimeText(r.createdAt)}</td><td><b>{r.action}</b></td><td>{r.entityType}</td><td className="mono">{r.entityId||"—"}</td></tr>)}</tbody></table></div>}</div><p className="hint page-hint">Keep the PC secured, regularly back up PostgreSQL, and don't expose the local database port to the internet.</p></>; }
function SettingsRow({label,value}:{label:string;value:string}) { return <div className="settings-row"><span>{label}</span><b>{value}</b></div>; }
function SubscriptionPage({company,email,role,settings,onRefresh,onNotice}:{company:Session["company"];email:string;role:string;settings:Row|null;onRefresh:()=>void;onNotice:(type:"success"|"error"|"info",text:string)=>void}) {
  const [plans,setPlans] = useState<Row[]>([]); const [selected,setSelected] = useState<Record<string,string>>({}); const [busyPlan,setBusyPlan] = useState("");
  const current = settings?.subscription; const requests:Row[] = settings?.planRequests ?? [];
  useEffect(()=>{ let live=true; api<{data:Row[]}> ("/api/plans").then(r=>{if(live)setPlans(r.data)}).catch(e=>onNotice("error",e instanceof Error?e.message:"Unable to load subscription plans.")); return ()=>{live=false}; },[]);
  async function requestPlan(plan:Row) { setBusyPlan(plan.id); try { const r=await api<{message:string}>("/api/subscription/request-plan",{method:"POST",body:JSON.stringify({planId:plan.id,billingCycle:selected[plan.id]||"MONTHLY"})}); onNotice("success",r.message); onRefresh(); } catch(e) { onNotice("error",e instanceof Error?e.message:"Unable to submit plan request."); } finally { setBusyPlan(""); } }
  const end = current?.periodEnd ? new Date(current.periodEnd) : null; const trialDays = end && current?.status === "TRIALING" ? Math.max(0,Math.ceil((end.getTime()-Date.now())/86400000)) : 0;
  return <div className="subscription-wrap">
    <div className="panel subscription-hero"><div className="subscription-icon"><CreditCard size={25}/></div><div className="eyebrow">SASTHA INFINITE ERP PLANS</div><h2>Choose a plan for your business</h2><p>Review your workspace, choose monthly or annual billing, and submit a request. The current version records your request but does not collect online payment yet.</p><span className={current?.status==="ACTIVE"?"status status-green":"status status-amber"}>{current?.status??"NO SUBSCRIPTION"}{current?.status==="TRIALING"?` · ${trialDays} trial day(s) left`:""}</span></div>
    <div className="panel"><div className="panel-heading"><div><h2>Workspace details</h2><p>Current account and subscription status</p></div><button className="secondary-button small" onClick={onRefresh}><RefreshCw size={14}/> Refresh</button></div><div className="settings-rows"><SettingsRow label="Company" value={company.name}/><SettingsRow label="Owner account" value={email}/><SettingsRow label="Access role" value={role.replaceAll("_"," ")}/><SettingsRow label="Current plan" value={current?.plan?.name??"No plan"}/><SettingsRow label="Subscription status" value={current?.status??"Not active"}/><SettingsRow label="Period ends" value={dateText(current?.periodEnd)}/><SettingsRow label="API address" value={API}/></div></div>
    <div className="plan-grid">{plans.map(plan=>{const limits=plan.limits??{};return <div className={`panel plan-card ${plan.code==="BUSINESS"?"plan-featured":""}`} key={plan.id}><div className="eyebrow">{plan.code==="BUSINESS"?"RECOMMENDED":"SUBSCRIPTION PLAN"}</div><h2>{plan.name}</h2><div className="plan-price">{money(plan.monthlyPrice)}<small>/month</small></div><div className="plan-annual">{money(plan.annualPrice)} / year</div><p>{limits.description??"ERP subscription plan"}</p><div className="plan-limit"><span>Users</span><b>{limits.maxUsers??"As agreed"}</b></div><div className="plan-limit"><span>Products</span><b>{Number(limits.maxProducts??0).toLocaleString("en-MY")}</b></div><div className="plan-limit"><span>Warehouses</span><b>{limits.maxWarehouses??"As agreed"}</b></div><label className="plan-cycle-label">Billing cycle<select value={selected[plan.id]||"MONTHLY"} onChange={e=>setSelected(v=>({...v,[plan.id]:e.target.value}))}><option value="MONTHLY">Monthly</option><option value="ANNUAL">Annual</option></select></label><button className="primary-button plan-button" disabled={!!busyPlan||requests.some(r=>r.status==="PENDING")} onClick={()=>requestPlan(plan)}>{busyPlan===plan.id?"Submitting…":"Request this plan"}</button></div>})}</div>
    {requests.length>0&&<div className="panel"><div className="panel-heading"><div><h2>Recent plan requests</h2><p>Requests await confirmation by Sastha Infinite Enterprise.</p></div></div>{requests.map(r=><div className="warehouse-row" key={r.id}><div className="record-icon"><CreditCard size={16}/></div><div><b>{r.plan?.name}</b><small>{r.note} · {dateText(r.createdAt)}</small></div><span className={statusClass(r.status)}>{r.status}</span></div>)}</div>}
    <div className="notice notice-warning"><div className="notice-icon"><CircleAlert size={18}/></div><div><b>Online payments are not connected yet</b><p>These are proposed launch prices and draft usage limits; usage limits are displayed but not yet enforced automatically. Plan requests are saved for follow-up, but no card or online payment is taken. Before public launch, confirm package limits and integrate a Malaysian payment gateway with verified webhooks. Do not advertise automated recurring billing until it is tested.</p></div></div>
  </div>;
}
